SetColumns(0);SetQuitOnError(true);SetMemoryLimit(12*10^9);
AttachSpec("work/degree9/shared/mdmagma/v2/mdmagma.spec");
tt:=Cputime();X:=MDX1(49,GF(2));FF:=FunctionField(Curve(X));AF,am:=AlgorithmicFunctionField(FF);assert Genus(AF) eq 69;
b:=am(X`_coordinates[1]);c:=am(X`_coordinates[2]);j:=(1+c)^12/(b^3*(b+c*(c+1)^3));cs:=Poles(j);assert Degree(j) eq 1176 and {*Degree(z):z in cs*} eq {*1^^21,3^^6,21*};rats:=[z:z in cs|Degree(z) eq 1];assert #rats eq 21;
printf "DECIC_C49_CUSP_PERMUTATION_MODEL_READY genus=69 rational=21 time=%o\n",Cputime(tt);
u:=am(X`_coordinates_xy[1]);v:=am(X`_coordinates_xy[2]);K:=BaseRing(AF);assert u eq AF!K.1 and v eq AF.1;
E:=EllipticCurve([am(z):z in X`_E]);P:=E![AF!0,AF!0];xy:=TateNormalForm_xy(E,2*P);sig0:=hom<K->AF|xy[1]>;dg:=hom<AF->AF|sig0,xy[2]>;
f23:=[am(z):z in X`_coordinates_F2F3];sigs:=[[Valuation(z,pl):z in f23]:pl in rats];assert #Seqset(sigs) eq 21;
images:=[[Valuation(dg(z),pl):z in f23]:pl in rats];perm:=[Index(sigs,ss):ss in images];assert Seqset(perm) eq Seqset([1..21]);
cyc:=[1];q:=perm[1];while q ne 1 do assert q notin cyc;Append(~cyc,q);q:=perm[q];end while;assert #cyc eq 21;
f:="work/deg10/next_cases_20261030/cyclic_primepowers/c49_cusp_permutation.m";
PrintFile(f,Sprintf("N:=49;rational_cusp_signatures:=%o;diamond2_image_signatures:=%o;diamond2_permutation:=%o;diamond2_cycle:=%o;",sigs,images,perm,cyc):Overwrite:=true);
PrintFile(f,"print \"DECIC_C49_CUSP_PERMUTATION_DATA_READY\";");
printf "DECIC_C49_CUSP_PERMUTATION_COMPLETE rational=21 unique_signatures=true diamond2_cycle=21 permutation=%o time=%o\n",perm,Cputime(tt);quit;
